package dev.slne.surf.api.common.invoker

import dev.slne.surf.api.shared.api.util.InternalSurfApi
import java.lang.constant.ClassDesc
import java.lang.invoke.MethodHandle
import java.lang.invoke.MethodHandles
import java.lang.invoke.MethodType
import java.lang.reflect.Method
import java.lang.reflect.Modifier

/**
 * Creates instances of the single-method interface [invokerType], one hidden class per
 * [MethodHandle].
 *
 * All instances share one class template generated by [HandleInvokerClasses]; each hidden class
 * holds its own handle as class data. The hidden classes are defined in [lookup], which needs full
 * privilege access and must see [invokerType].
 *
 * Thread-safe.
 *
 * @param I the invoker interface
 */
@InternalSurfApi
class InvokerFactory<I : Any>(
    private val invokerType: Class<I>,
    private val lookup: MethodHandles.Lookup,
) {

    private val invokerMethod = singleAbstractMethod(invokerType)

    /**
     * The type every handle passed to [create] is adapted to.
     */
    val invokerMethodType: MethodType = MethodType.methodType(
        invokerMethod.returnType,
        invokerMethod.parameterTypes,
    )

    /**
     * The bytecode of the shared class template.
     */
    val classBytes: ByteArray by lazy {
        HandleInvokerClasses.generate(
            ClassDesc.of(lookup.lookupClass().packageName, invokerType.simpleName + "Impl"),
            invokerType.describeConstable().orElseThrow(),
            listOf(
                InvokerMethod(
                    invokerMethod.name,
                    invokerMethodType.describeConstable().orElseThrow(),
                ),
            ),
        )
    }

    /**
     * Creates an invoker whose method calls [handle].
     *
     * [handle] is adapted to [invokerMethodType] with [MethodHandle.asType].
     *
     * @param handle the handle the invoker method calls
     * @return a new invoker in its own hidden class
     * @throws java.lang.invoke.WrongMethodTypeException if [handle] cannot be adapted
     */
    fun create(handle: MethodHandle): I {
        val adapted = handle.asType(invokerMethodType)
        val invoker = HandleInvokerClasses.instantiate(lookup, classBytes, listOf(adapted))

        return invokerType.cast(invoker)
    }

    private companion object {
        fun singleAbstractMethod(type: Class<*>): Method {
            require(type.isInterface) { "${type.name} is not an interface" }

            val abstractMethods = type.methods.filter { Modifier.isAbstract(it.modifiers) }

            return requireNotNull(abstractMethods.singleOrNull()) {
                "${type.name} must declare exactly one abstract method, found $abstractMethods"
            }
        }
    }
}
